__AR_EOF__
  emit "$root/system/sysctl/99-sysctl-monolith.conf" <<'__AR_EOF__'
# ===================================================================
# 1. ТЮНИНГ ПАМЯТИ И УМНОГО СЖАТИЯ (zRAM + zsmalloc)
# ===================================================================
# Агрессивно утилизируем сжатие в RAM, освобождая место под кэш
# (180 — канон для zram-only свопа: ядро охотнее жмёт страницы вместо
# прямых аллокаций под давлением; выровнено с серверами 2026-10-04)
vm.swappiness = 180

# Ранний фоновый reclaim (kswapd будить на 1.25% free вместо дефолтных
# 0.1%) — убирает direct-reclaim застревания; буст отключён: с zram он
# даёт лишнее давление при фрагментации без пользы
vm.watermark_scale_factor = 125
vm.watermark_boost_factor = 0

# Бережем кэш файловой системы, сбрасывая приложения в zRAM
vm.vfs_cache_pressure = 50

# Оптимизация отложенной записи на физический SSD (уменьшает фризы)
vm.dirty_ratio = 10
vm.dirty_background_ratio = 5

# ===================================================================
# 2. РАЗГОН СЕТЕВОГО СТЕКА (BBR + CAKE/FQ + WI-FI)
# ===================================================================
# Активация умного контроля заторов от Google и планировщика
net.core.default_qdisc = fq
net.ipv4.tcp_congestion_control = bbr
net.ipv4.tcp_fastopen = 3

# Защита от дропов пакетов в Docker и на Wi-Fi (увеличение очередей)
net.core.netdev_max_backlog = 10000
net.ipv4.tcp_max_syn_backlog = 8192

# Адаптивные TCP-буферы: канал до 1 Гбит/с × RTT 65-77ms -> BDP одного
# потока ~8-10MB, потолок 32M покрывает с запасом (измерено 2026-10-04,
# выровнено с серверным каноном; автотюнинг: память тратится по факту)
net.core.rmem_max = 33554432
net.core.wmem_max = 33554432
net.ipv4.tcp_rmem = 4096 262144 33554432
net.ipv4.tcp_wmem = 4096 65536 33554432
net.ipv4.tcp_moderate_rcvbuf = 1

# Автоматическое склеивание мелких пакетов в эфире
net.ipv4.tcp_autocorking = 1

# Клиентские длинные туннели (xray->ноды, измерено 2026-10-04: RTT 58-77ms,
# delivery ~100Mbps, retrans ~0.004%): не сбрасывать cwnd после простоя —
# после паузы туннель не тупит на разгоне; ограничить очередь отправки
# (меньше bufferbloat на upload); PLPMTUD на случай PMTU-чёрных дыр
# (Wi-Fi/VPN/ZeroTier)
net.ipv4.tcp_slow_start_after_idle = 0
net.ipv4.tcp_notsent_lowat = 131072
net.ipv4.tcp_mtu_probing = 1
__AR_EOF__
