[Service]
Type=oneshot
Nice=19
IOSchedulingClass=idle
ExecStart=/usr/bin/duperemove -dr --hashfile=/var/lib/duperemove_root.db -b 4k /usr/lib /usr/share /var/cache /opt
__AR_EOF__
