  emit "$root/dotfiles/eww/eww.scss" <<'__AR_EOF__'
// ══════════════════════════════════════════════════════════════
// ИМПОРТ ЦВЕТОВ PYWAL
// ══════════════════════════════════════════════════════════════

// pywal генерирует этот файл автоматически
