$blur-bg-dark: rgba($color0, 0.92);

$shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
$shadow-card: 0 4px 16px rgba(0, 0, 0, 0.3);

$transition-fast: 150ms ease;
$transition-normal: 250ms ease;
$transition-smooth: 350ms cubic-bezier(0.4, 0, 0.2, 1);

$font-main: "JetBrainsMono Nerd Font", monospace;


// ══════════════════════════════════════════════════════════════
// СБРОС И БАЗОВЫЕ СТИЛИ
// ══════════════════════════════════════════════════════════════

* {
  all: unset;
  font-family: $font-main;
  font-size: 13px;
}


// ══════════════════════════════════════════════════════════════
// HOTEDGE — невидимая триггер-зона
// ══════════════════════════════════════════════════════════════

.hotedge-trigger {
  background: transparent;
  // Можно добавить тонкую линию для визуального дебага:
  // border-bottom: 1px solid rgba($color4, 0.3);
}


// ══════════════════════════════════════════════════════════════
// ГАЛЕРЕЯ — основной контейнер
// ══════════════════════════════════════════════════════════════

.gallery-container {
  background: $blur-bg;
  border-bottom: 1px solid rgba($foreground, 0.08);
  box-shadow: $shadow;
  padding: 12px 20px 16px;
  
  // Градиент как в waybar
  background-image: linear-gradient(
    180deg,
    rgba($color4, 0.05) 0%,
    transparent 100%
  );
}


// ══════════════════════════════════════════════════════════════
// ЗАГОЛОВОК ГАЛЕРЕИ
// ══════════════════════════════════════════════════════════════

.gallery-header {
  padding: 0 4px 10px;
  margin-bottom: 4px;
  border-bottom: 1px solid rgba($foreground, 0.06);
}

.gallery-title {
  color: $foreground;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.5px;
  
  // Акцентный градиент как в rofi
  background: linear-gradient(90deg, $color4, $color5);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.gallery-close {
  color: rgba($foreground, 0.5);
  font-size: 16px;
  padding: 4px 8px;
  border-radius: $radius-small;
  transition: all $transition-fast;
  
  &:hover {
    color: $color1;
    background: rgba($color1, 0.15);
  }
}


// ══════════════════════════════════════════════════════════════
// СКРОЛЛ-КОНТЕЙНЕР
// ══════════════════════════════════════════════════════════════

.gallery-scroll {
  // Кастомный скроллбар (согласован с swaync)
  scrollbar {
    background: transparent;
    
    slider {
      background: rgba($foreground, 0.15);
      border-radius: 4px;
      min-width: 6px;
      min-height: 6px;
      
      &:hover {
        background: rgba($color4, 0.4);
      }
    }
  }
}

.gallery-list {
  padding: 4px 8px 8px;
}


// ══════════════════════════════════════════════════════════════
// КАРТОЧКИ ОБОЕВ
// ══════════════════════════════════════════════════════════════

.wallpaper-card {
  background: rgba($foreground, 0.03);
  border: 2px solid transparent;
  border-radius: $radius-medium;
  padding: 6px;
  transition: all $transition-normal;
  
  &:hover {
    background: rgba($foreground, 0.08);
    border-color: rgba($color4, 0.3);
    transform: translateY(-2px);
    box-shadow: $shadow-card;
    
    .card-preview {
      filter: brightness(1.05);
    }
  }
  
  // ВЫБРАННЫЙ ЭЛЕМЕНТ — акцентная подсветка
  &.selected {
    border-color: $color4;
    background: rgba($color4, 0.1);
    box-shadow: 
      0 0 0 1px rgba($color4, 0.3),
      0 4px 20px rgba($color4, 0.2);
    
    .card-preview {
      box-shadow: inset 0 0 0 2px rgba($color4, 0.4);
    }
    
    .card-name {
      color: $color4;
      font-weight: 600;
    }
  }
}


// ══════════════════════════════════════════════════════════════
// ПРЕВЬЮ ИЗОБРАЖЕНИЯ
// ══════════════════════════════════════════════════════════════

.card-preview {
  border-radius: $radius-small;
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  transition: all $transition-normal;
  position: relative;
  overflow: hidden;
  
  // Лёгкий vignette эффект
  &::after {
    content: "";
    position: absolute;
    inset: 0;
    background: radial-gradient(
      ellipse at center,
      transparent 50%,
      rgba(0, 0, 0, 0.15) 100%
    );
    pointer-events: none;
  }
}


// ══════════════════════════════════════════════════════════════
// ИНДИКАТОР "ТЕКУЩИЕ ОБОИ"
// ══════════════════════════════════════════════════════════════

.selected-indicator {
  opacity: 0;
  transform: scale(0.8);
  transition: all $transition-fast;
  
  margin: 6px;
  padding: 4px 8px;
  background: $color2;
  color: $color0;
  border-radius: $radius-small;
  font-size: 12px;
  font-weight: bold;
  
  box-shadow: 0 2px 8px rgba($color2, 0.4);
  
  &.visible {
    opacity: 1;
    transform: scale(1);
  }
}


// ══════════════════════════════════════════════════════════════
// НАЗВАНИЕ ФАЙЛА
// ══════════════════════════════════════════════════════════════

.card-name {
  color: rgba($foreground, 0.7);
  font-size: 11px;
  padding: 8px 4px 2px;
  text-align: center;
  transition: color $transition-fast;
}


// ══════════════════════════════════════════════════════════════
// АНИМАЦИИ ПОЯВЛЕНИЯ КАРТОЧЕК (stagger effect)
// ══════════════════════════════════════════════════════════════

@for $i from 1 through 20 {
  .gallery-list > *:nth-child(#{$i}) {
    animation: cardSlideIn 300ms ease #{$i * 30}ms backwards;
  }
}

@keyframes cardSlideIn {
  from {
    opacity: 0;
    transform: translateY(-10px) scale(0.95);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}
__AR_EOF__
  emit "$root/dotfiles/eww/eww.yuck" <<'__AR_EOF__'
;; ══════════════════════════════════════════════════════════════
;; ПЕРЕМЕННЫЕ
;; ══════════════════════════════════════════════════════════════

;; Видимость галереи (для анимации)
(defvar gallery-visible false)

;; Список обоев (обновляется при открытии)
(defvar wallpapers "[]")

;; Выбранный элемент (путь)
(defvar selected-wallpaper "")

;; Hover-таймер (чтобы не закрывалось мгновенно)
(defvar gallery-hover false)


;; ══════════════════════════════════════════════════════════════
;; ГОРЯЧАЯ ЗОНА (hotedge) — невидимая полоска вверху
;; ══════════════════════════════════════════════════════════════

(defwindow hotedge
  :monitor 0
  :stacking "overlay"
  :focusable false
  :exclusive false
  :namespace "eww-hotedge"
  :geometry (geometry
    :x "0%"
    :y "0px"
    :width "100%"
    :height "4px"
    :anchor "top center")
  
  (eventbox
    :class "hotedge-trigger"
    :onhover "${EWW_CMD} update gallery-visible=true && \
              ${EWW_CMD} update wallpapers=\"$(~/.config/eww/scripts/wallpaper-list.sh)\""
    (box)))


;; ══════════════════════════════════════════════════════════════
;; ГАЛЕРЕЯ ОБОЕВ — горизонтальный scroll с превью
;; ══════════════════════════════════════════════════════════════

(defwindow wallpaper-gallery
  :monitor 0
  :stacking "overlay"
  :focusable true
  :exclusive false
  :namespace "eww-gallery"
  :geometry (geometry
    :x "0%"
    :y "0px"
    :width "100%"
    :height "220px"
    :anchor "top center")
  
  (eventbox
    :onhover "${EWW_CMD} update gallery-hover=true"
    :onhoverlost "${EWW_CMD} update gallery-hover=false && \
                  sleep 0.3 && \
                  ${EWW_CMD} update gallery-visible=false"
    
    (revealer
      :transition "slidedown"
      :reveal gallery-visible
      :duration "350ms"
      
      (box
        :class "gallery-container"
        :orientation "v"
        :space-evenly false
        
        ;; Заголовок с кнопкой закрытия
        (box
          :class "gallery-header"
          :orientation "h"
          :space-evenly false
          
          (label :class "gallery-title" :text "󰸉  Wallpapers")
          (box :hexpand true)
          (button
            :class "gallery-close"
            :onclick "${EWW_CMD} update gallery-visible=false"
            "󰅖"))
        
        ;; Горизонтальный скролл с карточками
        (scroll
          :class "gallery-scroll"
          :hscroll true
          :vscroll false
          :hexpand true
          :vexpand true
          
          (box
            :class "gallery-list"
            :orientation "h"
            :space-evenly false
            :spacing 16
            
            (for wp in wallpapers
              (wallpaper-card
                :path {wp.path}
                :thumb {wp.thumb}
                :name {wp.name}
                :is-selected {wp.selected}))))))))


;; ══════════════════════════════════════════════════════════════
;; ВИДЖЕТ КАРТОЧКИ ОБОЕВ
;; ══════════════════════════════════════════════════════════════

(defwidget wallpaper-card [path thumb name is-selected]
  (eventbox
    :class "card-eventbox"
    :onclick "~/.local/bin/wallpaperctl set '${path}' && \
              ${EWW_CMD} update wallpapers=\"$(~/.config/eww/scripts/wallpaper-list.sh)\" && \
              sleep 1.5 && ${EWW_CMD} update gallery-visible=false"
    :cursor "pointer"
    
    (box
      :class "wallpaper-card ${is-selected ? 'selected' : ''}"
      :orientation "v"
      :space-evenly false
      
      ;; Превью
      (box
        :class "card-preview"
        :style "background-image: url('${thumb}');"
        :width 240
        :height 135
        
        ;; Индикатор "текущие обои"
        (box
          :class "selected-indicator ${is-selected ? 'visible' : ''}"
          :halign "end"
          :valign "start"
          (label :text "󰄬")))
      
      ;; Название файла
      (label
        :class "card-name"
        :limit-width 22
        :text name))))
__AR_EOF__
  emit "$root/dotfiles/eww/scripts/wallpaper-list.sh" <<'__AR_EOF__'
#!/usr/bin/env bash
set -euo pipefail

WALLDIR="$HOME/Изображения/Wallpapers"
THUMB_DIR="$HOME/.config/eww/images/thumbnails"
THUMB_SIZE="280x160"
STATE_FILE="${XDG_STATE_HOME:-$HOME/.local/state}/wallpaper/current"

mkdir -p "$THUMB_DIR"

# Получаем текущие обои (для подсветки)
current=""
[[ -f "$STATE_FILE" ]] && current="$(cat "$STATE_FILE")"

# Собираем JSON массив
json="["
first=true

while IFS= read -r -d '' img; do
  name="$(basename "$img")"
  thumb="$THUMB_DIR/${name%.*}.jpg"
  
  # Генерируем thumbnail если нет или старее оригинала
  if [[ ! -f "$thumb" ]] || [[ "$img" -nt "$thumb" ]]; then
    convert "$img" -thumbnail "$THUMB_SIZE^" \
      -gravity center -extent "$THUMB_SIZE" \
      -quality 85 "$thumb" 2>/dev/null || continue
  fi
  
  # Определяем, выбран ли этот элемент
  selected="false"
  [[ "$img" == "$current" ]] && selected="true"
  
  $first || json+=","
  first=false
  
  # Экранируем путь для JSON
  json+="$(printf '{"path":"%s","thumb":"%s","name":"%s","selected":%s}' \
    "$img" "$thumb" "$name" "$selected")"

done < <(find "$WALLDIR" -maxdepth 1 -type f \
  \( -iname '*.png' -o -iname '*.jpg' -o -iname '*.jpeg' -o -iname '*.webp' -o -iname '*.gif' \) \
  -print0 | sort -z)

json+="]"
echo "$json"
__AR_EOF__
  emit "$root/dotfiles/ferrite/config.toml" <<'__AR_EOF__'
# Ferrite — пользовательский конфиг.
# Аналог бывшего bash-статусбара (~/.config/sway/status.sh):
# lang | cpu mem temp bat | net bt vol bri | time | date.
# Режим i3bar (цвета/иконки/pango + клики), nerd-пак иконок — как в bash.

[bar]
render_interval_ms = 250
protocol = "i3bar"
markup = "pango"
# Шаблон строки: {модуль} через любой буквальный текст-разделитель.
# Разделителей сколько угодно и каких угодно — дефолтные: пробел внутри группы,
# " | " между группами. {date} ниже = «11:30 | 26 июня», поэтому хвост сам даёт
# «| TIME | DATE». load/disk убраны — их в bash-статусбаре не было.
layout = "{lang} | {cpu} {mem} {temp} {bat} | {net} {bt} {vol} {bri} | {date}"
default_color = "#cdd6f4"
separator_block_width = 0   # 0 = всё расстояние несут разделители из layout (как в bash)
click_events = true

[icons]
pack = "nerd"
[icons.overrides]

# Какие модули запускать задаётся {name} в [bar].layout выше.
[modules]

[modules.lang]
shorten = 2
fallback = "KB"

[modules.cpu]
interval_ms = 1000
icon = ""

[modules.mem]
interval_ms = 2000
format = "used"
icon = ""

[modules.temp]
interval_ms = 2000
zone = "auto"
icon = ""
critical = 75

[modules.battery]
interval_ms = 5000
device = "auto"

[modules.net]
interval_ms = 3000
signal = "percent"
interfaces = ["wifi", "lan"]  # показывать и Wi-Fi, и LAN (каждое подключённое физ. NIC)
show_ip = true
show_rate = false          # в bash rx/tx не показывался
rate_threshold_kb = 1

[modules.bluetooth]
interval_ms = 5000
backend = "dbus"          # event-driven, 0 forks — вместо bluetoothctl из bash

[modules.volume]
interval_ms = 2000
timeout_ms = 800

[modules.brightness]
interval_ms = 2000
device = "auto"

[modules.date]
interval_ms = 1000
format = "[hour]:[minute] | [day] [month repr:long]"
locale = "ru"              # русские названия месяцев: «26 июня»

# Клики по частям бара. Ключ = имя модуля (как {name} в [bar].layout),
# внутри — номер кнопки → shell-команда (запуск через sh -c, можно трубы/$term).
# Кнопки: 1=left 2=middle 3=right 4=wheel-up 5=wheel-down. "*" = любая другая.
# Модули без записи здесь просто не реагируют на клик (0 стоимости в простое).
[click_actions]
vol  = { 1 = "pamixer -t", 3 = "swaymsg exec pavucontrol", 4 = "pamixer -i 5", 5 = "pamixer -d 5" }   # ЛКМ=mute, ПКМ=pavucontrol, колесо=±5%
bri  = { 4 = "brightnessctl set 5%+", 5 = "brightnessctl set 5%-" }     # колесо=яркость ±5%
cpu  = { 1 = "swaymsg exec '$term -e top'" }                           # ЛКМ=top (btop нет)
mem  = { 1 = "swaymsg exec '$term -e top'" }                           # ЛКМ=top
temp = { 1 = "swaymsg exec '$term -e watch -n1 sensors'" }             # ЛКМ=sensors
bat  = { 1 = "swaymsg exec '$term -e watch -n2 cat /sys/class/power_supply/BAT0/capacity /sys/class/power_supply/BAT0/status'" }  # ЛКМ=sysfs (upower/acpi нет)
net  = { 1 = "swaymsg exec '$term -e nmtui'" }                         # ЛКМ=nmtui (rofi-network-manager нет)
bt   = { 1 = "swaymsg exec '$term -e bluetoothctl'" }                  # ЛКМ=bluetoothctl (rofi-bluetooth нет)
lang = { 1 = "swaymsg input type:keyboard xkb_switch_layout $(swaymsg -t get_inputs | python3 -c \"import sys,json; d=json.load(sys.stdin); kb=next((i for i in d if 'keyboard' in i.get('identifier','').lower() and i.get('xkb_active_layout_name')),None); print(0 if kb and 'Russian' in kb['xkb_active_layout_name'] else 1)\")" }  # ЛКМ=us<->ru (xkb_switch_pattern next — no-op без pattern)
date = { 1 = "swaymsg exec 'rofi -show calendar -modi calendar'" }     # ЛКМ=календарь
__AR_EOF__
