  emit "$root/dotfiles/rofi/bin/logout" <<'__AR_EOF__'
#!/usr/bin/env bash

#-----------------------------------------------------------------------------
# ROFI LOGOUT SCRIPT - 2x2 GRID LAYOUT
# Updated for Square Buttons & Glassmorphism
#-----------------------------------------------------------------------------

# Theme Path
theme="$HOME/.config/rofi/themes/logout_menu.rasi"

# Options (Using Nerd Fonts for Icons)
# Note: Added spaces for visual balance in vertical layout
LOCK=''
LOGOUT='󰍃'
REBOOT=''
SHUTDOWN=''
SUSPEND='󰒲'

YES='       Да'
NO='       Нет'

# Rofi Command Wrapper
rofi_cmd() {
	rofi -dmenu \
		-theme "${theme}" \
		-p "Goodbye" \
        -mesg "Select Action"
}

# Confirmation Command Wrapper
# Refactored to match the glass aesthetic without external theme file dependency for this part
confirm_cmd() {
	rofi -theme-str 'window {location: center; anchor: center; fullscreen: false; width: 350px; background-color: rgba(20,20,20,0.9); border: 2px; border-color: rgba(255,255,255,0.1); border-radius: 24px;}' \
		-theme-str 'mainbox {children: [ "message", "listview" ]; spacing: 15px; padding: 30px;}' \
		-theme-str 'message {padding: 10px; background-color: transparent;}' \
		-theme-str 'textbox {text-color: white; horizontal-align: 0.5;}' \
		-theme-str 'listview {columns: 2; lines: 1; spacing: 15px;}' \
		-theme-str 'element {border-radius: 12px; padding: 15px; background-color: rgba(255,255,255,0.1);}' \
		-theme-str 'element selected {background-color: white; text-color: black;}' \
		-theme-str 'element-text {horizontal-align: 0.5;}' \
		-dmenu \
		-p 'Confirmation' \
		-mesg 'Вы уверены?' \
		-theme "${theme}"
}

# Ask for confirmation
confirm_exit() {
	echo -e "$YES\n$NO" | confirm_cmd
}

# Generate Menu Options
# NOTE: We strictly output 4 items to ensure a perfect 2x2 grid.
# 'Suspend' is commented out to maintain symmetry. Uncomment to add it back (will break 2x2).
run_rofi() {
	echo -e "$LOCK\n$LOGOUT\n$REBOOT\n$SHUTDOWN" | rofi_cmd
}

# Execute Logic
run_cmd() {
	selected="$(confirm_exit)"
	if [[ "$selected" == "$YES" ]]; then
		if [[ $1 == '--shutdown' ]]; then
			systemctl poweroff
		elif [[ $1 == '--reboot' ]]; then
			systemctl reboot
		elif [[ $1 == '--suspend' ]]; then
			systemctl suspend
		elif [[ $1 == '--logout' ]]; then
            # Session Detection & Exit
			if [[ "$DESKTOP_SESSION" == 'openbox' ]]; then
				openbox --exit
			elif [[ "$DESKTOP_SESSION" == 'bspwm' ]]; then
				bspc quit
			elif [[ "$DESKTOP_SESSION" == 'i3' ]]; then
				i3-msg exit
			elif [[ "$DESKTOP_SESSION" == 'plasma' ]]; then
				qdbus org.kde.ksmserver /KSMServer logout 0 0 0
			elif [[ "$XDG_SESSION_DESKTOP" == 'Hyprland' ]]; then
                # Hyprland specific cleanup
                pkill gammastep
                hyprctl dispatch exit
			fi
		fi
	else
		exit 0
	fi
}

# Main Execution Block
chosen="$(run_rofi)"
case ${chosen} in
    $SHUTDOWN)
		run_cmd --shutdown
        ;;
    $REBOOT)
		run_cmd --reboot
        ;;
    $LOCK)
		# Lock immediately without confirmation
        # Adjust command based on your locker (swaylock/hyprlock)
		loginctl lock-session
        ;;
    $SUSPEND)
		run_cmd --suspend
        ;;
    $LOGOUT)
		run_cmd --logout
        ;;
esac
__AR_EOF__
  emit "$root/dotfiles/rofi/bin/run" <<'__AR_EOF__'
#!/bin/bash

rofi -theme ~/.config/rofi/themes/launcher.rasi \
     -theme-str 'mainbox {children: [ "inputbar", "message", "listview"];}' \
     -no-show-icons \
     -modi run \
     -show run 
__AR_EOF__
  emit "$root/dotfiles/rofi/config.rasi" <<'__AR_EOF__'
/*******************************************************************************
 * ROFI CONFIG - WAYBAR UNIFIED THEME
 * 
 * Based on Waybar Aesthetics:
 * 1. Capsule/Pill Geometry (border-radius: 99px for internal elements)
 * 2. High Transparency Glass (rgba(20, 20, 20, 0.3))
 * 3. Thin 1px Borders with low opacity
 *******************************************************************************/

configuration {
    modi:                       "drun,run";
    show-icons:                 true;
    display-drun:               "APPS";
    display-run:                "RUN";
    drun-display-format:        "{name}";
    font:                       "JetBrainsMono Nerd Font Bold 12";
}

/*******************************************************************************
 * GLOBAL PROPERTIES & COLOR MAPPING
 *******************************************************************************/
@import "~/.cache/wal/colors-rofi-dark.rasi"

* {
    /* 
     * WAYBAR COLOR MATCHING
     * Waybar Reference: rgba(20, 20, 20, 0.3) -> Hex approx #1414144D
     * Waybar Border: alpha(@foreground, 0.2)
     */
    
    /* Main Window Background (Glassy & Light like Waybar) */
    bg-glass:       #1414144D; 
    
    /* Element Backgrounds (Transparent by default) */
    bg-trans:       transparent;

    /* Selected Element (Active Capsule) */
    bg-selected:    @selected-normal-background;

    /* Borders: Low opacity based on foreground approximation */
    border-glass:   #ffffff33; 

    /* Text Colors */
    fg-main:        @foreground;
    fg-dim:         @foreground; 
    
    /* Reset */
    background-color:   transparent;
    text-color:         @fg-main;

    margin:     0px;
    padding:    0px;
    spacing:    0px;
}

/*******************************************************************************
 * WINDOW LAYOUT
 *******************************************************************************/
window {
    transparency:   "real";
    width:          450px; /* Slightly wider for aesthetics */
    
    /* 
     * Outer container keeps a structured rounded rect, 
     * while inner elements will be capsules.
     */
    border-radius:  24px;
    
    location:       center;
    anchor:         center;
    
    background-color:   @bg-glass;
    
    /* Thin border matching Waybar */
    border:             1px;
    border-color:       @border-glass;
}

/*******************************************************************************
 * MAIN CONTAINER
 *******************************************************************************/
mainbox {
    padding:    12px;
    children:   [ inputbar, listview ];
    spacing:    10px;
}

/*******************************************************************************
 * INPUT BAR (SEARCH CAPSULE)
 *******************************************************************************/
inputbar {
    /* Capsule Shape - Distinct Waybar Feature */
    background-color:   @bg-glass;
    border:             1px;
    border-color:       @border-glass;
    border-radius:      99px;

    padding:    10px 20px; /* Comfortable padding inside capsule */
    spacing:    10px;
    children:   [ prompt, entry ];
}

prompt {
    text-color: @selected-normal-background; /* Accent color for prompt */
}

entry {
    placeholder:        "Search...";
    placeholder-color:  #ffffff66;
    text-color:         @fg-main;
}

/*******************************************************************************
 * LIST VIEW
 *******************************************************************************/
listview {
    background-color:   transparent;
    margin:     5px 0 0;
    lines:      7;
    columns:    1;
    fixed-height: false;
    border:       0px;
    spacing:      4px; /* Space between element capsules */
}

/*******************************************************************************
 * ELEMENTS (ROWS -> CAPSULES)
 *******************************************************************************/
element {
    padding:        8px 16px;
    spacing:        10px;
    
    /* Transforming rows into floating capsules */
    border-radius:  99px;
    background-color: transparent;
    text-color:       @fg-main;
    border:           0px;
}

/* Hover/Active States */
element normal active {
    text-color: @selected-normal-background;
}

element selected normal, element selected active {
    background-color:   rgba(255, 255, 255, 0.1); /* Subtle hover effect */
    border:             1px;
    border-color:       @border-glass;
    text-color:         @selected-normal-background;
}

element-icon {
    size:           20px;
    vertical-align: 0.5;
}

element-text {
    vertical-align: 0.5;
    text-color:     inherit;
    font-weight:    bold; /* Matching Waybar Bold font */
}

/*******************************************************************************
 * EXTRAS
 *******************************************************************************/
message {
    margin:             10px 0 0;
    border-radius:      99px;
    border-color:       @border-glass;
    background-color:   @bg-glass;
    padding:            8px;
}

textbox {
    padding:    8px 24px;
    text-color: @fg-main;
}
__AR_EOF__
  emit "$root/dotfiles/rofi/scripts/cliphist-rofi-img" <<'__AR_EOF__'
#!/usr/bin/env bash

tmp_dir="/tmp/cliphist"
rm -rf "$tmp_dir"

if [[ -n "$1" ]]; then
    cliphist decode <<<"$1" | wl-copy
    exit
fi

mkdir -p "$tmp_dir"

read -r -d '' prog <<EOF
/^[0-9]+\s<meta http-equiv=/ { next }
match(\$0, /^([0-9]+)\s(\[\[\s)?binary.*(jpg|jpeg|png|bmp)/, grp) {
    system("echo " grp[1] "\\\\\t | cliphist decode >$tmp_dir/"grp[1]"."grp[3])
    print \$0"\0icon\x1f$tmp_dir/"grp[1]"."grp[3]
    next
}
1
EOF
cliphist list | gawk "$prog"
__AR_EOF__
  emit "$root/dotfiles/rofi/themes/bookmarks.rasi" <<'__AR_EOF__'
@import "colors/tokyonight.rasi"

* {
    font: "CaskaydiaCove Nerd Font, bold 12";
    background-color: transparent;
    margin: 0px;
    padding: 0px;
    spacing: 0px;
}

window {
    location: north;
    y-offset: -37px;
    width: 750px;
    border-radius: 0px 0px 15px 15px;
    background-color: @background;
}

mainbox {
    padding: 12px;
    children: ["listview", "inputbar"];
}

inputbar {
    background-color: @background-alt;
    border: 2px;
    border-radius: 15px;
    padding: 8px 16px;
    spacing: 8px;
    children: [entry];
}

entry {
    placeholder: "Search bookmark:";
    text-color: @foreground; 
}

textbox {
    padding: 24px;
}

listview {
    margin: 0 0 10px 0;
    lines: 5;
    columns: 1;
    fixed-height: false;
    scrollbar: true;
}

scrollbar {
    handle-width:  2px;
    handle-color:  @background-sec;
    border-radius: 20px;
