    selected:                    @color1;
    
    /* Неактивные элементы - единый стиль */
    inactive-bg:                 rgba(255, 255, 255, 0.08);
    inactive-fg:                 @foreground;
    inactive-border:             rgba(255, 255, 255, 0.05);
    
    /* Активный (выделенный) элемент */
    active-bg:                   @color1;
    active-fg:                   @background;
    active-border:               @color1;
}

/*****----- Main Window -----*****/
window {
    transparency:                "real";
    location:                    center;
    anchor:                      center;
    fullscreen:                  false;
    width:                       500px; 
    x-offset:                    0px;
    y-offset:                    0px;

    /* Glassmorphism Style */
    enabled:                     true;
    margin:                      0px;
    padding:                     0px;
    border:                      2px solid;
    border-radius:               24px;
    border-color:                rgba(255, 255, 255, 0.1);
    cursor:                      "default";
    background-color:            rgba(20, 20, 20, 0.6);
}

/*****----- Main Box -----*****/
mainbox {
    enabled:                     true;
    spacing:                     20px;
    margin:                      0px;
    padding:                     40px;
    border:                      0px solid;
    border-radius:               0px;
    border-color:                @selected;
    background-color:            transparent;
    children:                    [ "listview" ];
}

/*****----- Inputbar (Hidden) -----*****/
inputbar {
    enabled:                     false;
}

/*****----- Listview -----*****/
listview {
    enabled:                     true;
    columns:                     2;
    lines:                       2;
    cycle:                       true;
    dynamic:                     true;
    scrollbar:                   false;
    layout:                      vertical;
    reverse:                     false;
    fixed-height:                true;
    fixed-columns:               true;
    spacing:                     20px;
    margin:                      0px;
    padding:                     0px;
    border:                      0px solid;
    background-color:            transparent;
    cursor:                      "default";
}

/*****----- Elements (The Buttons) -----*****/
element {
    enabled:                     true;
    spacing:                     15px;
    margin:                      0px;
    padding:                     35px 10px;
    border:                      1px solid;
    border-radius:               20px;
    cursor:                      pointer;
    orientation:                 vertical;
    
    /* По умолчанию - неактивный стиль */
    background-color:            @inactive-bg;
    text-color:                  @inactive-fg;
    border-color:                @inactive-border;
}

/*****----- Все неактивные состояния - ОДИНАКОВЫЙ ЦВЕТ -----*****/
element normal.normal,
element alternate.normal,
element normal.urgent,
element alternate.urgent,
element normal.active,
element alternate.active {
    background-color:            @inactive-bg;
    text-color:                  @inactive-fg;
    border-color:                @inactive-border;
}

/*****----- Выделенный элемент - ОТЛИЧАЕТСЯ -----*****/
element selected.normal,
element selected.urgent,
element selected.active {
    background-color:            @active-bg;
    text-color:                  @active-fg;
    border-color:                @active-border;
}

/*****----- Element Text -----*****/
element-text {
    background-color:            transparent;
    text-color:                  inherit;
    cursor:                      inherit;
    vertical-align:              0.5;
    horizontal-align:            0.5;
}
