# ╔══════════════════════════════════════════════════════════════════════════════╗
# ║                              STARSHIP CONFIG                                  ║
# ╚══════════════════════════════════════════════════════════════════════════════╝

"$schema" = 'https://starship.rs/config-schema.json'


# ╔══════════════════════════════════════════════════════════════════════════════╗
# ║                          ОСНОВНОЙ ФОРМАТ ПРОМПТА                             ║
# ╚══════════════════════════════════════════════════════════════════════════════╝

# ⚠️ Модуль $cpp НЕ СУЩЕСТВУЕТ в Starship — C++ определяется через модуль $c

format = """
$os\
$username\
$hostname\
$directory\
$git_branch\
$git_commit\
$git_status\
$docker_context\
$aws\
$gcloud\
$buf\
$cmake\
$meson\
$xmake\
$bun\
$deno\
$conda\
$nix_shell\
$python\
$package\
$golang\
$nodejs\
$rust\
$c\
$crystal\
$dart\
$elixir\
$elm\
$fennel\
$fortran\
$haskell\
$haxe\
$java\
$julia\
$kotlin\
$lua\
$nim\
$ocaml\
$perl\
$php\
$rlang\
$ruby\
$scala\
$swift\
$zig\
$memory_usage\
$cmd_duration\
$status\
$line_break\
$character"""


# ╔══════════════════════════════════════════════════════════════════════════════╗
# ║                            МОДУЛЬ ОС (ИКОНКИ)                                ║
# ╚══════════════════════════════════════════════════════════════════════════════╝

[os]
disabled = false
format = "[$symbol]($style) "
style = "bold white"

[os.symbols]
Arch = " "
Artix = " "
CachyOS = " "
EndeavourOS = " "
Garuda = " "
Manjaro = " "
Debian = " "
Ubuntu = " "
Pop = " "
Mint = " "
Raspbian = " "
Kali = " "
Fedora = " "
CentOS = " "
AlmaLinux = " "
RockyLinux = " "
Redhat = " "
RedHatEnterprise = " "
Nobara = " "
openSUSE = " "
SUSE = " "
Gentoo = " "
NixOS = " "
Void = " "
Alpine = " "
Solus = " "
FreeBSD = " "
OpenBSD = " "
NetBSD = " "
DragonFly = " "
HardenedBSD = " "
MidnightBSD = " "
Macos = " "
Windows = " "
Amazon = " "
Android = " "
OracleLinux = " "
Alpaquita = " "
AOSC = " "
Emscripten = " "
Illumos = " "
Mabox = " "
Mariner = " "
Redox = " "
Linux = " "
Unknown = " "


# ╔══════════════════════════════════════════════════════════════════════════════╗
# ║                          ДИРЕКТОРИЯ / ПУТЬ                                   ║
# ╚══════════════════════════════════════════════════════════════════════════════╝

# ⚠️ truncation_length = 0 может создать очень длинный промпт

[directory]
truncation_length = 0
fish_style_pwd_dir_length = 0
truncate_to_repo = false
read_only = " "
home_symbol = "~"
style = "bold cyan"
format = "[$path]($style)[$read_only]($read_only_style) "


# ╔══════════════════════════════════════════════════════════════════════════════╗
# ║                              GIT МОДУЛИ                                       ║
# ╚══════════════════════════════════════════════════════════════════════════════╝

[git_branch]
symbol = " "
style = "bold purple"
format = "on [$symbol$branch(:$remote_branch)]($style) "

[git_commit]
commit_hash_length = 7
tag_symbol = " "
style = "bold yellow"
only_detached = false
tag_disabled = false
format = "[$hash$tag]($style) "

[git_status]
style = "bold red"
ahead = "⇡${count}"
behind = "⇣${count}"
diverged = "⇕⇡${ahead_count}⇣${behind_count}"
staged = "+${count}"
modified = "!${count}"
untracked = "?${count}"
deleted = "✘${count}"
stashed = "📦"
format = "([\\[$all_status$ahead_behind\\]]($style) )"


# ╔══════════════════════════════════════════════════════════════════════════════╗
# ║                              DOCKER                                           ║
# ╚══════════════════════════════════════════════════════════════════════════════╝

[docker_context]
symbol = " "
only_with_files = true
detect_files = ["docker-compose.yml", "docker-compose.yaml", "Dockerfile", "compose.yml"]
style = "bold blue"
format = "via [$symbol$context]($style) "


# ╔══════════════════════════════════════════════════════════════════════════════╗
# ║                         CLOUD & INFRASTRUCTURE                               ║
# ╚══════════════════════════════════════════════════════════════════════════════╝

[aws]
symbol = " "
format = "on [$symbol($profile )(\\($region\\) )]($style)"

[gcloud]
symbol = " "
format = "on [$symbol$account(@$domain)(\\($region\\))]($style) "


# ╔══════════════════════════════════════════════════════════════════════════════╗
# ║                            BUILD SYSTEMS                                      ║
# ╚══════════════════════════════════════════════════════════════════════════════╝

[buf]
symbol = " "
format = "via [$symbol($version )]($style)"

[cmake]
symbol = " "
format = "via [$symbol($version )]($style)"

[meson]
symbol = " "
format = "via [$symbol$version]($style) "

[xmake]
symbol = " "
format = "via [$symbol($version )]($style)"


# ╔══════════════════════════════════════════════════════════════════════════════╗
# ║                       RUNTIMES & PACKAGE MANAGERS                            ║
# ╚══════════════════════════════════════════════════════════════════════════════╝

[bun]
symbol = " "
format = "via [$symbol($version )]($style)"

[deno]
symbol = " "
format = "via [$symbol($version )]($style)"

[conda]
symbol = " "
format = "via [$symbol$environment]($style) "

[nix_shell]
symbol = " "
format = "via [$symbol$state( \\($name\\))]($style) "


# ╔══════════════════════════════════════════════════════════════════════════════╗
# ║                        ЯЗЫКИ ПРОГРАММИРОВАНИЯ                                ║
# ╚══════════════════════════════════════════════════════════════════════════════╝

[python]
symbol = " "
style = "bold yellow"
format = "via [${symbol}${pyenv_prefix}(${version} )(\\($virtualenv\\))]($style) "
detect_extensions = ["py"]
detect_files = ["requirements.txt", "pyproject.toml", "Pipfile", ".python-version"]

[package]
symbol = "📦 "
style = "bold 208"
format = "is [$symbol$version]($style) "
display_private = true

[golang]
symbol = " "
style = "bold cyan"
format = "via [$symbol($version )]($style)"

[nodejs]
symbol = " "
style = "bold green"
format = "via [$symbol($version )]($style)"
detect_files = ["package.json", ".nvmrc"]

[rust]
symbol = " "
style = "bold red"
format = "via [$symbol($version )]($style)"

# ⚠️ Этот модуль обрабатывает и C, и C++ (detect_extensions включает .cpp, .hpp)
[c]
symbol = " "
style = "bold blue"
format = "via [$symbol($version(-$name) )]($style)"
detect_extensions = ["c", "h", "cpp", "hpp", "cxx"]

[crystal]
symbol = " "
format = "via [$symbol($version )]($style)"

[dart]
symbol = " "
format = "via [$symbol($version )]($style)"

[elixir]
symbol = " "
format = "via [$symbol($version \\(OTP $otp_version\\) )]($style)"

[elm]
symbol = " "
format = "via [$symbol($version )]($style)"

[fennel]
symbol = " "
format = "via [$symbol($version )]($style)"

[fortran]
symbol = " "
format = "via [$symbol($version )]($style)"

[haskell]
symbol = " "
format = "via [$symbol($version )]($style)"

[haxe]
symbol = " "
format = "via [$symbol($version )]($style)"

[java]
symbol = " "
format = "via [$symbol($version )]($style)"

[julia]
symbol = " "
format = "via [$symbol($version )]($style)"

[kotlin]
symbol = " "
format = "via [$symbol($version )]($style)"

[lua]
symbol = " "
format = "via [$symbol($version )]($style)"

[nim]
symbol = " "
format = "via [$symbol($version )]($style)"

[ocaml]
symbol = " "
format = "via [$symbol($version )(\\($switch_indicator$switch_name\\) )]($style)"

[perl]
symbol = " "
format = "via [$symbol($version )]($style)"

[php]
symbol = " "
format = "via [$symbol($version )]($style)"

[rlang]
symbol = " "
format = "via [$symbol($version )]($style)"

[ruby]
symbol = " "
format = "via [$symbol($version )]($style)"

[scala]
symbol = " "
format = "via [$symbol($version )]($style)"

[swift]
symbol = " "
format = "via [$symbol($version )]($style)"

[zig]
symbol = " "
format = "via [$symbol($version )]($style)"


# ╔══════════════════════════════════════════════════════════════════════════════╗
# ║                          УТИЛИТАРНЫЕ МОДУЛИ                                  ║
# ╚══════════════════════════════════════════════════════════════════════════════╝

[memory_usage]
symbol = " "
disabled = true
format = "via $symbol[$ram( | $swap)]($style) "

[cmd_duration]
min_time = 2_000
format = "took [$duration]($style) "
style = "bold yellow"

[username]
show_always = false
style_user = "bold green"
style_root = "bold red"
format = "[$user]($style)@"

[hostname]
ssh_only = true
style = "bold green"
format = "[$hostname]($style) in "

[status]
disabled = false
symbol = "✘"
format = "[$symbol $status]($style) "
style = "bold red"

[character]
success_symbol = "[❯](bold green)"
error_symbol = "[❯](bold red)"
vimcmd_symbol = "[❮](bold green)"
__AR_EOF__
  emit "$root/dotfiles/sway/config" <<'__AR_EOF__'
# =======================================================================================
#   SWAY MASTER CONFIG (ADAPTED FROM HYPRLAND)
# =======================================================================================

# ---------------------------------------------------------------------------------------
# 1. ПЕРЕМЕННЫЕ И ЦВЕТА (PYWAL)
# ---------------------------------------------------------------------------------------
# Подключаем сгенерированные цвета
include ~/.cache/wal/colors-sway

# Основные переменные
set $mod Mod4
set $term alacritty
set $menu rofi -show drun

# ---------------------------------------------------------------------------------------
# 2. МОНИТОРЫ
# ---------------------------------------------------------------------------------------
# В Sway синтаксис: output <name> scale <factor>
output * scale 1.15

# ---------------------------------------------------------------------------------------
# 3. АВТОЗАПУСК
# ---------------------------------------------------------------------------------------
# Важные демоны
exec /usr/lib/polkit-gnome/polkit-gnome-authentication-agent-1
exec dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP=sway

# Интерфейс
# Запускаем swayidle (конфигурация ниже или через отдельный файл, здесь базовая команда)
# exec swayidle -w \
#     timeout 300 'swaylock -f -c 000000' \
#     timeout 600 'swaymsg "output * power off"' \
#     resume 'swaymsg "output * power on"' \
#     before-sleep 'swaylock -f -c 000000'

# Важно: убедитесь, что awww запущен (если еще не добавили в автостарт)
exec_always awww-daemon

xwayland enable

# Буфер обмена
exec wl-paste --type text --watch cliphist store -max-items 50
exec wl-paste --type image --watch cliphist store -max-items 50

# ---------------------------------------------------------------------------------------
# 4. ВНЕШНИЙ ВИД (Gaps, Borders, Decoration)
# ---------------------------------------------------------------------------------------
# Отступы (gaps)
# gaps inner 5
# gaps outer 10

# Рамки окон
default_border pixel 2
default_floating_border pixel 2

# Шрифт (опционально, наследуется системой, но можно задать)
font pango:Noto Sans 10
# ---------------------------------------------------------------------------------------

# ---------------------------------------------------------------------------------------
# 5. ВВОД (INPUT)
# ---------------------------------------------------------------------------------------
input type:keyboard {
    xkb_layout us,ru
    xkb_options grp:win_space_toggle,grp:alt_shift_toggle
}

input type:touchpad {
    tap enabled
    natural_scroll enabled
    middle_emulation enabled
    pointer_accel 0.5
    drag_lock disabled
}

# ThinkPad T14s Gen 1 — ETPS/2 Elantech Touchpad (трекпоинт + тачпад + 3 механические кнопки)
# Перекрываем per-type настройки для этого устройства:
#   • Левая кнопка трекпоинта = левый клик (BTN_LEFT)
#   • Правая кнопка трекпоинта = правый клик (BTN_RIGHT)
#   • Центральная кнопка = средний клик (BTN_MIDDLE) + при удержании + движение трекпоинта = скролл
input "2:14:ETPS/2_Elantech_Touchpad" {
    tap enabled
    natural_scroll enabled
    # Физическая средняя кнопка есть — эмуляция через Л+П не нужна
    middle_emulation disabled
    pointer_accel 0.5
    drag_lock disabled
    # Классический ThinkPad scroll: зажать среднюю кнопку + двигать трекпоинт
    scroll_method on_button_down
    scroll_button BTN_MIDDLE
    # Нижняя зона тачпада разделена на левую/правую кнопки
    click_method button_areas
}

# Примечание: в sway можно делать per-device биндинги мыши через
#   bindsym --input-device="2:14:ETPS/2_Elantech_Touchpad" --whole-window button1 exec ...
# но это перехватывает события глобально и ломает обычные клики в приложениях.
# Стандартное поведение кнопок настраивается через блок input выше.

# Мышь
input type:pointer {
    accel_profile flat
    pointer_accel 0.5
}

# ---------------------------------------------------------------------------------------
# 6. КЛАВИШИ (BINDINGS)
# ---------------------------------------------------------------------------------------

# -- Приложения --
bindsym $mod+Return exec $term
bindsym $mod+e exec thunar
bindsym $mod+b exec firefox

# -- Управление окнами --
bindsym $mod+q kill
bindsym $mod+Shift+q exec swaymsg exit
bindsym $mod+f floating toggle
bindsym $mod+m fullscreen toggle
bindsym $mod+Shift+f fullscreen toggle

# -- Перемещение фокуса --
bindsym $mod+Left focus left
bindsym $mod+Down focus down
bindsym $mod+Up focus up
bindsym $mod+Right focus right

# -- Перемещение окон --
bindsym $mod+Shift+Left move left
bindsym $mod+Shift+Down move down
bindsym $mod+Shift+Up move up
bindsym $mod+Shift+Right move right

# -- Лаунчеры и Меню --
# Rofi
bindsym $mod+D exec $menu
# Cliphist (буфер обмена через rofi)
bindsym $mod+v exec rofi -modi clipboard:~/.config/rofi/scripts/cliphist-rofi-img -show clipboard
# Wlogout
bindsym $mod+Escape exec wlogout

# -- Скриншоты (Grim + Slurp) --
# Просто скриншот в буфер
bindsym Print exec grim -g "$(slurp)" - | wl-copy
# Скриншот в файл
bindsym Shift+Print exec grim -g "$(slurp)" "$HOME/Изображения/Снимки экрана/$(date +'%Y-%m-%d-%H%M%S.png')"

# -- Мультимедиа клавиши --
bindsym --locked XF86AudioRaiseVolume exec pamixer -i 5
bindsym --locked XF86AudioLowerVolume exec pamixer -d 5
bindsym --locked XF86AudioMute exec pamixer -t
bindsym --locked XF86AudioMicMute exec pamixer --default-source -t
bindsym --locked XF86MonBrightnessUp exec brightnessctl s 10%+
bindsym --locked XF86MonBrightnessDown exec brightnessctl s 10%-

# Перезагрузка конфига Sway (нужна, чтобы применились новые цвета Pywal)
bindsym $mod+Shift+c reload

# Выход из Sway (завершение сессии)
bindsym $mod+Shift+e exec swaynag -t warning -m 'Вы действительно хотите выйти?' -B 'Да, выйти' 'swaymsg exit'

# Меню выбора обоев (Swallpaper)
bindsym $mod+w exec ~/.local/bin/wall-select

# ---------------------------------------------------------------------------------------
# 7. РАБОЧИЕ СТОЛЫ (WORKSPACES)
# ---------------------------------------------------------------------------------------
# Переключение
bindsym $mod+1 workspace number 1
bindsym $mod+2 workspace number 2
bindsym $mod+3 workspace number 3
bindsym $mod+4 workspace number 4
bindsym $mod+5 workspace number 5
bindsym $mod+6 workspace number 6

# Перенос окна на рабочий стол
bindsym $mod+Shift+1 move container to workspace number 1
bindsym $mod+Shift+2 move container to workspace number 2
bindsym $mod+Shift+3 move container to workspace number 3
bindsym $mod+Shift+4 move container to workspace number 4
bindsym $mod+Shift+5 move container to workspace number 5
bindsym $mod+Shift+6 move container to workspace number 6

# ---------------------------------------------------------------------------------------
# 8. МЫШЬ (FLOATING MODIFIER)
# ---------------------------------------------------------------------------------------
# Позволяет перетаскивать окна мышкой, зажав Super
floating_modifier $mod normal

# ---------------------------------------------------------------------------------------
# 9. ПРАВИЛА ОКОН (WINDOW RULES)
# ---------------------------------------------------------------------------------------
# Жесты (Sway поддерживает простые жесты переключения столов)
bindgesture swipe:3:right workspace prev
bindgesture swipe:3:left workspace next

# =======================================================================================
# 10. STATUS BAR (NATIVE SWAYBAR)
# =======================================================================================
bar {
    # Позиция
    position top

    # Команда, которая генерирует текст (наш скрипт)
    status_command  ~/.config/sway/ferrite

    # Настройки трея
    tray_output *
    tray_padding 5

    # Шрифт бара (должен совпадать с тем, что был в waybar для иконок)
    font pango:JetBrainsMono Nerd Font 10

    # Разделитель между блоками воркспейсов
    workspace_min_width 30
    
    # Цветовая схема (интеграция с Pywal)
    # $background и другие переменные берутся из include ~/.cache/wal/colors-sway
    # Если переменные называются иначе в colors-sway, замените их ниже.
    # Обычно colors-sway генерирует: client.focused $color15 $color0 ...
    # Но для бара нужны конкретные HEX коды или переменные.
    
    colors {
        # Цвет фона бара
        background $background
        # Цвет текста статусной строки
        statusline $foreground
        # Цвет разделителя
        separator  $color8

        # Состояния кнопок воркспейсов
        #                  border      background  text
        focused_workspace  $color4     $color4     $background
        active_workspace   $color8     $color8     $foreground
        inactive_workspace $background $background $foreground
        urgent_workspace   $color1     $color1     $foreground
    }
}
__AR_EOF__
  emit "$root/dotfiles/sway/status.sh" <<'__AR_EOF__'
#!/usr/bin/env bash
set -o pipefail
LC_ALL=C

# ---------------- настройки ----------------
TICK="0.5"       # тик (сек). 0.2 = 5 раз/сек печать строки
TMO_FAST="0.25s" # таймаут для emerge (чтобы не фризило)
TMO_SLOW="0.8s"  # таймаут для обычных модулей

# EMERGE: обновляются вне очереди
EMERGE_LANG=1
EMERGE_NET=1
EMERGE_BT=1

# Как часто вызывать emerge-модули (в тиках)
LANG_EVERY=1 # 0.2s
NET_EVERY=5  # 1.0s при TICK=0.2
BT_EVERY=10  # 2.0s при TICK=0.2

# Очередь (только НЕ-emerge)
SCHEDULE=(vol bri cpu mem temp bat date)
# ------------------------------------------

# single instance (после reload не копим процессы)
SCRIPT="$(readlink -f "$0" 2>/dev/null || echo "$0")"
for pid in $(pgrep -f "$SCRIPT" 2>/dev/null || true); do
	[ "$pid" -ne "$$" ] && kill "$pid" 2>/dev/null || true
done

run_fast() { timeout "$TMO_FAST" "$@" 2>/dev/null; }
run_slow() { timeout "$TMO_SLOW" "$@" 2>/dev/null; }

BAT_PATH="$(find /sys/class/power_supply/ -name "BAT*" 2>/dev/null | head -n1)"
THERM_ZONE="$(find /sys/class/thermal/ -name "thermal_zone*" 2>/dev/null | head -n1)"

# ---------------- getters ----------------

get_lang() {
	# Проверяем зависимости
	if ! command -v swaymsg >/dev/null 2>&1 || ! command -v jq >/dev/null 2>&1; then
		echo "KB"
		return
	fi

	local lang
	# 1. Запрашиваем raw JSON (-r)
	# 2. Ищем объекты, у которых поле xkb_active_layout_name не пустое
	# 3. Извлекаем имя первой найденной раскладки
	lang=$(swaymsg -t get_inputs -r | jq -r '
    .[] 
    | select(.xkb_active_layout_name != null) 
    | .xkb_active_layout_name
  ' | head -n1)

	# Если Sway вернул что-то вроде "English (US)", берем первые 2 буквы и в капс
	if [ -n "$lang" ]; then
		echo "$lang" | cut -c1-2 | tr '[:lower:]' '[:upper:]'
	else
		echo "KB"
	fi
}

get_cpu() {
	# считает по общей строке "cpu" через Δ за интервал (по умолчанию 1 сек)
	# формула ровно как в твоём awk: u = user+system ($2+$4), t = user+system+idle ($2+$4+$5)
	# вывод: целое число процентов (дробь отсекается)
	local interval="${1:-1}"

	awk -v interval="$interval" '
    function sample(   line,f,u,s,i) {
      while ((getline line < "/proc/stat") > 0) {
        if (line ~ /^cpu[[:space:]]/) {
          split(line, f, /[[:space:]]+/)
          u = f[2] + 0
          s = f[4] + 0
          i = f[5] + 0
          close("/proc/stat")
          return (u+s) " " (u+s+i)
        }
      }
      close("/proc/stat")
      return "0 0"
    }

    BEGIN {
      split(sample(), a, " "); u1=a[1]; t1=a[2]
      system("sleep " interval)
      split(sample(), b, " "); u2=b[1]; t2=b[2]

      du = u2 - u1
      dt = t2 - t1

      if (dt <= 0 || du < 0) pct = 0
      else pct = int((du*100 + dt/2) / dt)   # округление до целого

      if (pct < 0) pct = 0
      if (pct > 100) pct = 100

      printf " %d%%\n", pct
    }
  '
}

get_mem() {
	local used
	used=$(free -h | awk '/^Mem/ {print $3}' | sed 's/Gi/G/g;s/Mi/M/g')
	echo " $used"
}

get_temp() {
	[ -z "${THERM_ZONE:-}" ] && {
		echo ""
		return
	}
	[ -f "$THERM_ZONE/temp" ] || {
		echo ""
		return
	}
	local temp
	temp=$(cat "$THERM_ZONE/temp" 2>/dev/null || true)
	[ -n "${temp:-}" ] && echo " $((temp / 1000))°"
}

get_battery() {
	[ -z "${BAT_PATH:-}" ] && {
		echo ""
		return
	}
	local cap status icon
	cap=$(cat "$BAT_PATH/capacity" 2>/dev/null || true)
	status=$(cat "$BAT_PATH/status" 2>/dev/null || true)
	[ -z "${cap:-}" ] && {
		echo ""
		return
	}

	if [ "$status" = "Charging" ]; then
		icon=""
	else
		if [ "$cap" -ge 90 ]; then
			icon="󰁹"
		elif [ "$cap" -ge 70 ]; then
			icon="󰂂"
		elif [ "$cap" -ge 50 ]; then
			icon="󰁾"
		elif [ "$cap" -ge 30 ]; then
			icon="󰁼"
		else
			icon="󰁺"
		fi
	fi
	echo "$icon $cap%"
}

get_volume() {
	command -v pamixer >/dev/null 2>&1 || {
		echo ""
		return
	}
	local vol mute icon
	vol=$(run_slow pamixer --get-volume || true)
	mute=$(run_slow pamixer --get-mute || true)

	if [ "$mute" = "true" ]; then
		echo "󰖁 Mute"
		return
	fi
	[ -z "${vol:-}" ] && {
		echo ""
		return
	}

	if [ "$vol" -lt 30 ]; then
		icon=""
	elif [ "$vol" -lt 70 ]; then
		icon=""
	else
		icon=""
	fi
	echo "$icon $vol%"
}

get_brightness() {
	command -v brightnessctl >/dev/null 2>&1 || {
		echo ""
		return
	}
	local perc icon
	perc=$(brightnessctl -m 2>/dev/null | head -n1 | awk -F, '{gsub(/%/,"",$4); print $4}')
	[ -z "${perc:-}" ] && {
		echo ""
		return
	}

	if [ "$perc" -lt 30 ]; then
		icon="󰃞"
	elif [ "$perc" -lt 70 ]; then
		icon="󰃟"
	else
		icon="󰃠"
	fi
	echo "$icon ${perc}%"
}

wifi_icon_from_signal() {
	local s="${1:-0}"
	if [ "$s" -ge 80 ]; then
		echo "󰤨"
	elif [ "$s" -ge 60 ]; then
		echo "󰤥"
	elif [ "$s" -ge 40 ]; then
		echo "󰤢"
	elif [ "$s" -ge 20 ]; then
		echo "󰤟"
	else
		echo "󰤯"
	fi
}
dbm_to_percent() {
	local dbm="$1"
	local p=$((2 * (dbm + 100)))
	[ "$p" -lt 0 ] && p=0
	[ "$p" -gt 100 ] && p=100
	echo "$p"
}

get_net() {
	local dev ip4
	dev=$(ip route show default 2>/dev/null | awk 'NR==1{print $5}')
	[ -z "${dev:-}" ] && {
		echo "󰈀 Off"
		return
	}

	ip4=$(ip -4 -o addr show dev "$dev" scope global 2>/dev/null | awk 'NR==1{print $4}' | cut -d/ -f1)
	ip4=${ip4:-noip}

	if [ -d "/sys/class/net/$dev/wireless" ] && command -v iw >/dev/null 2>&1; then
		local link ssid dbm sig icon
		link=$(run_fast iw dev "$dev" link || true)

		if echo "$link" | grep -q "Not connected"; then
			echo "󰤯 WiFi Off"
			return
		fi

		ssid=$(echo "$link" | awk -F': ' '/SSID:/{print $2; exit}')
		dbm=$(echo "$link" | awk '/signal:/{print $2; exit}' | cut -d. -f1)

		[ -z "${ssid:-}" ] && ssid="WiFi"
		if [[ "${dbm:-}" =~ ^-?[0-9]+$ ]]; then sig=$(dbm_to_percent "$dbm"); else sig=0; fi
		icon=$(wifi_icon_from_signal "$sig")
		echo "$icon $ssid ${sig}% $ip4"
		return
	fi

	echo "󰈀 Wired $ip4"
}

get_bt() {
	command -v bluetoothctl >/dev/null 2>&1 || {
		echo ""
		return
	}

	local powered line name
	powered=$(run_fast bluetoothctl show | awk '/Powered:/{print $2; exit}')
	if [ "$powered" != "yes" ]; then
		echo "󰂲"
		return
	fi

	line=$(run_fast bluetoothctl devices Connected | head -n1 || true)
	if [ -n "${line:-}" ]; then
		name=$(echo "$line" | cut -d' ' -f3-)
		echo " $name"
	else
		echo " On"
	fi
}

get_date() { date +'%H:%M | %d %B'; }

# ---------------- cache ----------------
lang="KB"
cpu=""
mem=""
temp=""
bat=""
net="󰈀 Off"
bt=""
vol=""
bri=""
datestr=""

print_status() {
	printf "%s | %s %s %s %s | %s %s %s %s | %s\n" \
		"$lang" "$cpu" "$mem" "$temp" "$bat" \
		"$net" "$bt" "$vol" "$bri" \
		"$datestr"
}

# обновляем значение только если не пусто (чтобы при таймауте не мигало)
assign_if_nonempty() {
	# $1=varname $2=value
	[ -n "${2:-}" ] && printf -v "$1" '%s' "$2"
}

update_all_once() {
	assign_if_nonempty lang "$(get_lang)"
	assign_if_nonempty cpu "$(get_cpu)"
	assign_if_nonempty mem "$(get_mem)"
	assign_if_nonempty temp "$(get_temp)"
	assign_if_nonempty bat "$(get_battery)"
	assign_if_nonempty net "$(get_net)"
	assign_if_nonempty bt "$(get_bt)"
	assign_if_nonempty vol "$(get_volume)"
	assign_if_nonempty bri "$(get_brightness)"
	assign_if_nonempty datestr "$(get_date)"
}

# ---- старт: все модули сразу ----
update_all_once
print_status

# ---- основной цикл ----
i=0
n=${#SCHEDULE[@]}
tickno=0

while true; do
	tickno=$((tickno + 1))

	# EMERGE (вне очереди), но с throttling
	if [ "${EMERGE_LANG:-0}" -eq 1 ] && [ $((tickno % LANG_EVERY)) -eq 0 ]; then
		assign_if_nonempty lang "$(get_lang)"
	fi
	if [ "${EMERGE_NET:-0}" -eq 1 ] && [ $((tickno % NET_EVERY)) -eq 0 ]; then
		assign_if_nonempty net "$(get_net)"
	fi
	if [ "${EMERGE_BT:-0}" -eq 1 ] && [ $((tickno % BT_EVERY)) -eq 0 ]; then
		assign_if_nonempty bt "$(get_bt)"
	fi

	# Один модуль из очереди за тик
	mod="${SCHEDULE[$i]}"
	case "$mod" in
	vol) assign_if_nonempty vol "$(get_volume)" ;;
	bri) assign_if_nonempty bri "$(get_brightness)" ;;
	cpu) assign_if_nonempty cpu "$(get_cpu)" ;;
	mem) assign_if_nonempty mem "$(get_mem)" ;;
	temp) assign_if_nonempty temp "$(get_temp)" ;;
	bat) assign_if_nonempty bat "$(get_battery)" ;;
	date) assign_if_nonempty datestr "$(get_date)" ;;
	esac

	print_status

	i=$(((i + 1) % n))
	sleep "$TICK"
done
