/*******************************************************************************
 * SWAYNC STYLE - WAYBAR UNIFIED (FIXED ALIGNMENT)
 *******************************************************************************/
@import "../../.cache/wal/colors-waybar.css";

* {
    font-family: "JetBrainsMono Nerd Font";
    font-weight: bold;
    font-size: 13px;
}

/* ГЛАВНЫЙ КОНТЕЙНЕР */
.control-center {
    background: rgba(20, 20, 20, 0.3);
    border-radius: 24px;
    border: 1px solid alpha(@foreground, 0.2);
    box-shadow: none;
    padding: 14px;
}

/* ЗАГОЛОВОК И ВЕРХНИЕ КНОПКИ */
.widget-title {
    color: @foreground;
    margin-bottom: 8px;
}

/* Специфичное правило для текста заголовка (Уведомления) */
.widget-title > label {
    font-size: 20px;
    margin: 4px 0px 4px 8px;
}

.widget-title > button {
    background: rgba(255, 255, 255, 0.1);
    color: @foreground;
    border: 1px solid alpha(@foreground, 0.1);
    box-shadow: none;
    border-radius: 99px;
    padding: 6px 16px;
    font-weight: bold;
    font-size: 13px;
}

.widget-title > button:hover {
    background: @color4;
    color: @background;
    border-color: @color4;
}

/* ВИДЖЕТ "НЕ БЕСПОКОИТЬ" (DND) */
.widget-dnd {
    background: rgba(20, 20, 20, 0.3);
    color: @foreground;
    padding: 8px 20px;
    margin: 8px 4px;
    border-radius: 99px;
    border: 1px solid alpha(@foreground, 0.1);
}

.widget-dnd > switch {
    border-radius: 99px;
    background: alpha(@foreground, 0.2);
}

.widget-dnd > switch:checked {
    background: @color4;
}

/* ЛЕЙБЛЫ */
.widget-label {
    margin: 8px 4px;
}
.widget-label > label {
    color: @foreground;
}

/* ПЛЕЕР (MPRIS) */
.widget-mpris {
    background: rgba(20, 20, 20, 0.3);
    border: 1px solid alpha(@foreground, 0.2);
    border-radius: 24px;
    padding: 10px;
    margin: 10px 4px;
    color: @foreground;
}

.widget-mpris > button {
    border-radius: 99px;
}

/* НИЖНИЕ КНОПКИ / МЕНЮ (GRID) */
.widget-menubar {
    background: transparent;
    margin-top: 10px;
    margin-bottom: 0px;
}

.widget-menubar > box {
    margin: 0px 4px;
    spacing: 10px;
}

.widget-menubar > box > button {
    border-radius: 99px;
    background: rgba(255, 255, 255, 0.1);
    padding: 8px 16px;
    border: 1px solid alpha(@foreground, 0.1);
}

.widget-menubar > box > button:hover {
    background: @color4;
    color: @background;
}

/* УВЕДОМЛЕНИЯ */
.notification-row {
    outline: none;
    margin: 6px 0;
}

.notification {
    background: rgba(20, 20, 20, 0.3);
    border-radius: 16px; 
    padding: 12px;
    border: 1px solid alpha(@foreground, 0.2);
    box-shadow: none;
}

/* Пустой список уведомлений */
.notification-list > label {
    font-size: 14px;
    color: alpha(@foreground, 0.6);
}

.summary {
    color: @color4;
    font-size: 14px;
}

.time {
    color: alpha(@foreground, 0.6);
    font-size: 11px;
}

.body {
    color: @foreground;
}

/* Кнопки действий в уведомлениях */
.notification-action {
    border-radius: 99px;
    background: alpha(@background, 0.5);
    border: 1px solid alpha(@foreground, 0.2);
    color: @foreground;
    padding: 4px 12px;
}

.notification-action:hover {
    background: @color4;
    color: @background;
}
